// One-bit thermostat controller. Implemented as a combinational function,
// the output signals (heater, aircon, fan) directly depend on the inputs
// (mode, too_cold, too_hot, fan_on).
module TopModule (
    input  mode,
    input  too_cold,
    input  too_hot,
    input  fan_on,
    output heater,
    output aircon,
    output fan
);
    wire heater_on = mode & too_cold;
    wire ac_on = !mode & too_hot;
    wire fan_on_i = heater_on | ac_on | fan_on;
    assign {heater, aircon, fan} = {heater_on, ac_on, fan_on_i};
endmodule

